+});"},{"sha":"12bb59c270ce777f747d3aea94a63e58465d9a18","filename":"web/src/features/chat/components/prompt-toolbar/toolbar-queue.tsx","status":"added","additions":160,"deletions":0,"changes":160,"blob_url":"https://github.com/MoonshotAI/kimi-cli/blob/6915c5e2f4310a7e12501e10acbf75115b55cd9e/web%2Fsrc%2Ffeatures%2Fchat%2Fcomponents%2Fprompt-toolbar%2Ftoolbar-queue.tsx","raw_url":"https://github.com/MoonshotAI/kimi-cli/raw/6915c5e2f4310a7e12501e10acbf75115b55cd9e/web%2Fsrc%2Ffeatures%2Fchat%2Fcomponents%2Fprompt-toolbar%2Ftoolbar-queue.tsx","contents_url":"https://api.github.com/repos/MoonshotAI/kimi-cli/contents/web%2Fsrc%2Ffeatures%2Fchat%2Fcomponents%2Fprompt-toolbar%2Ftoolbar-queue.tsx?ref=6915c5e2f4310a7e12501e10acbf75115b55cd9e","patch":"@@ -0,0 +1,160 @@
