+import {
+  type ReactElement,
+  memo,
+  useCallback,
+  useEffect,
+  useRef,
+  useState,
+} from "react";
+import { cn } from "@/lib/utils";
+import type { GitDiffStats } from "@/lib/api/models";
+import { useQueueStore } from "../../queue-store";
+import { ToolbarActivityIndicator, type ActivityDetail } from "../activity-status-indicator";
+import { ToolbarQueuePanel, ToolbarQueueTab } from "./toolbar-queue";
+import { ToolbarChangesPanel, ToolbarChangesTab } from "./toolbar-changes";
+
+// ─── Types ───────────────────────────────────────────────────
+
+type TabId = "queue" | "changes";
+
+type PromptToolbarProps = {
+  gitDiffStats?: GitDiffStats | null;
+  isGitDiffLoading?: boolean;
+  workDir?: string | null;
+  activityStatus?: ActivityDetail;
+};
+
+// ─── Main toolbar ────────────────────────────────────────────
+
+export const PromptToolbar = memo(function PromptToolbarComponent({
+  gitDiffStats,
+  isGitDiffLoading,
+  workDir,
+  activityStatus,
+}: PromptToolbarProps): ReactElement | null {
+  const queue = useQueueStore((s) => s.queue);
+  const [activeTab, setActiveTab] = useState<TabId | null>(null);
+  const prevQueueLenRef = useRef(0);
+
+  const stats = gitDiffStats;
+  const hasChanges = Boolean(stats?.isGitRepo && stats.hasChanges && stats.files && !stats.error);
+  const hasQueue = queue.length > 0;
+  const hasTabs = hasQueue || hasChanges;
+
+  // Auto-open queue tab when first item is added
+  useEffect(() => {
+    if (prevQueueLenRef.current === 0 && queue.length > 0) {
+      setActiveTab("queue");
+    }
+    prevQueueLenRef.current = queue.length;
+  }, [queue.length]);
+
+  // Auto-close tab when its data becomes empty
+  useEffect(() => {
+    if (activeTab === "queue" && !hasQueue) setActiveTab(null);
+    if (activeTab === "changes" && !hasChanges) setActiveTab(null);
+  }, [activeTab, hasQueue, hasChanges]);
+
+  const toggleTab = useCallback((tab: TabId) => {
+    setActiveTab((prev) => (prev === tab ? null : tab));
+  }, []);
+
+  if (!(hasTabs || activityStatus)) return null;
+
+  return (
+    <div className={cn("w-full px-1 sm:px-2 flex flex-col gap-1 mb-2", isGitDiffLoading && "opacity-70")}>
+      {/* ── Expanded panel ── */}
+      {activeTab && (
+        <div className="max-h-32 overflow-y-auto rounded-md border border-border bg-background py-1 px-0.5">
+          {activeTab === "queue" && <ToolbarQueuePanel queue={queue} />}
+          {activeTab === "changes" && stats && (
+            <ToolbarChangesPanel stats={stats} workDir={workDir} />
+          )}
+        </div>
+      )}
+
+      {/* ── Tab bar ── */}
+      <div className="flex items-center gap-1.5 px-1">
+        {activityStatus && (
+          <ToolbarActivityIndicator activity={activityStatus} />
+        )}
+
+        {hasQueue && (
+          <ToolbarQueueTab
+            count={queue.length}
+            isActive={activeTab === "queue"}
+            onToggle={() => toggleTab("queue")}
+          />
+        )}
+
+        {hasChanges && stats?.files && (
+          <ToolbarChangesTab
+            stats={stats}
+            workDir={workDir}
+            isActive={activeTab === "changes"}
+            onToggle={() => toggleTab("changes")}
+          />
+        )}
+      </div>
+    </div>
+  );
+});"},{"sha":"97c475b2f89229143b5649ae399b84b97895db69","filename":"web/src/features/chat/components/prompt-toolbar/open-in-button.tsx","status":"added","additions":98,"deletions":0,"changes":98,"blob_url":"https://github.com/MoonshotAI/kimi-cli/blob/6915c5e2f4310a7e12501e10acbf75115b55cd9e/web%2Fsrc%2Ffeatures%2Fchat%2Fcomponents%2Fprompt-toolbar%2Fopen-in-button.tsx","raw_url":"https://github.com/MoonshotAI/kimi-cli/raw/6915c5e2f4310a7e12501e10acbf75115b55cd9e/web%2Fsrc%2Ffeatures%2Fchat%2Fcomponents%2Fprompt-toolbar%2Fopen-in-button.tsx","contents_url":"https://api.github.com/repos/MoonshotAI/kimi-cli/contents/web%2Fsrc%2Ffeatures%2Fchat%2Fcomponents%2Fprompt-toolbar%2Fopen-in-button.tsx?ref=6915c5e2f4310a7e12501e10acbf75115b55cd9e","patch":"@@ -0,0 +1,98 @@
+import { type ReactElement, useCallback, useMemo } from "react";
+import {
+  CopyIcon,
+  ExternalLinkIcon,
+  FolderOpenIcon,
+  CodeIcon,
+  AppWindowIcon,
+} from "lucide-react";
+import { toast } from "sonner";
+import {
+  DropdownMenu,
+  DropdownMenuContent,
+  DropdownMenuItem,
+  DropdownMenuSeparator,
+  DropdownMenuTrigger,
+} from "@/components/ui/dropdown-menu";
+import { cn } from "@/lib/utils";
+import { getAuthHeader } from "@/lib/auth";
+import { isMacOS } from "@/hooks/utils";
+
+type OpenTarget = {
+  id: string;
+  label: string;
+  icon: ReactElement;
+  backendApp: "finder" | "cursor" | "vscode";
+};
+
+const OPEN_TARGETS: OpenTarget[] = [
+  { id: "finder", label: "Finder", icon: <FolderOpenIcon className="size-3.5" />, backendApp: "finder" },
+  { id: "cursor", label: "Cursor", icon: <AppWindowIcon className="size-3.5" />, backendApp: "cursor" },
+  { id: "vscode", label: "VS Code", icon: <CodeIcon className="size-3.5" />, backendApp: "vscode" },
+];
+
+async function openViaBackend(app: OpenTarget["backendApp"], path: string) {
+  const response = await fetch("/api/open-in", {
+    method: "POST",
+    headers: { "Content-Type": "application/json", ...getAuthHeader() },
+    body: JSON.stringify({ app, path }),
+  });
+  if (!response.ok) {
+    let detail = "Failed to open application.";
+    try {
+      const data = await response.json();
+      if (data?.detail) detail = String(data.detail);
+    } catch { /* ignore */ }
+    throw new Error(detail);
+  }
+}
+
+export function OpenInButton({ path, className }: { path: string; className?: string }) {
+  const targets = useMemo(() => (isMacOS() ? OPEN_TARGETS : OPEN_TARGETS.filter((t) => t.id !== "finder")), []);
+
+  const handleOpen = useCallback(async (target: OpenTarget, e: Event) => {
+    e.stopPropagation();
+    try { await openViaBackend(target.backendApp, path); }
+    catch (error) { toast.error("Failed to open", { description: error instanceof Error ? error.message : "Unexpected error" }); }
+  }, [path]);
+
+  const handleCopyPath = useCallback(async (e: Event) => {
+    e.stopPropagation();
+    try { await navigator.clipboard.writeText(path); toast.success("Path copied", { description: path }); }
+    catch { toast.error("Failed to copy path"); }
+  }, [path]);
+
+  return (
+    <DropdownMenu>
+      <DropdownMenuTrigger asChild>
+        <button
+          type="button"
+          onClick={(e) => e.stopPropagation()}
+          className={cn(
+            "inline-flex items-center gap-1 rounded px-1.5 py-0.5",
+            "text-[10px] font-medium text-muted-foreground",
+            "bg-background/80 hover:bg-background hover:text-foreground",
+            "border border-border/50 shadow-sm transition-all duration-150 cursor-pointer",
+            className,
+          )}
+        >
+          <ExternalLinkIcon className="size-2.5" />
+          <span>Open</span>
+        </button>
