+});"},{"sha":"13012fc40ddc197caf1a443af851250e4e8ff5b7","filename":"web/src/features/chat/queue-store.ts","status":"added","additions":46,"deletions":0,"changes":46,"blob_url":"https://github.com/MoonshotAI/kimi-cli/blob/6915c5e2f4310a7e12501e10acbf75115b55cd9e/web%2Fsrc%2Ffeatures%2Fchat%2Fqueue-store.ts","raw_url":"https://github.com/MoonshotAI/kimi-cli/raw/6915c5e2f4310a7e12501e10acbf75115b55cd9e/web%2Fsrc%2Ffeatures%2Fchat%2Fqueue-store.ts","contents_url":"https://api.github.com/repos/MoonshotAI/kimi-cli/contents/web%2Fsrc%2Ffeatures%2Fchat%2Fqueue-store.ts?ref=6915c5e2f4310a7e12501e10acbf75115b55cd9e","patch":"@@ -0,0 +1,46 @@
+import { create } from "zustand";
+
+export interface QueuedItem {
+  id: string;
+  text: string;
+}
+
+type QueueStore = {
+  queue: QueuedItem[];
+  enqueue: (text: string) => void;
+  removeFromQueue: (id: string) => void;
+  editQueueItem: (id: string, text: string) => void;
+  moveQueueItemUp: (id: string) => void;
+  dequeue: () => QueuedItem | undefined;
+  clearQueue: () => void;
+};
+
+export const useQueueStore = create<QueueStore>((set, get) => ({
+  queue: [],
+  enqueue: (text) =>
+    set((s) => ({
+      queue: [...s.queue, { id: crypto.randomUUID(), text }],
+    })),
+  removeFromQueue: (id) =>
+    set((s) => ({ queue: s.queue.filter((q) => q.id !== id) })),
+  editQueueItem: (id, text) =>
+    set((s) => ({
+      queue: s.queue.map((q) => (q.id === id ? { ...q, text } : q)),
+    })),
+  moveQueueItemUp: (id) =>
+    set((s) => {
+      const idx = s.queue.findIndex((q) => q.id === id);
+      if (idx <= 0) return s;
+      const next = [...s.queue];
+      [next[idx - 1], next[idx]] = [next[idx], next[idx - 1]];
+      return { queue: next };
+    }),
+  dequeue: () => {
+    const { queue } = get();
+    if (queue.length === 0) return undefined;
+    const [first, ...rest] = queue;
+    set({ queue: rest });
+    return first;
+  },
+  clearQueue: () => set({ queue: [] }),
+}));"},{"sha":"17c2b6f7b8b728fa333ac769f66022f2be0878d1","filename":"web/src/hooks/useSessionStream.ts","status":"modified","additions":3,"deletions":3,"changes":6,"blob_url":"https://github.com/MoonshotAI/kimi-cli/blob/6915c5e2f4310a7e12501e10acbf75115b55cd9e/web%2Fsrc%2Fhooks%2FuseSessionStream.ts","raw_url":"https://github.com/MoonshotAI/kimi-cli/raw/6915c5e2f4310a7e12501e10acbf75115b55cd9e/web%2Fsrc%2Fhooks%2FuseSessionStream.ts","contents_url":"https://api.github.com/repos/MoonshotAI/kimi-cli/contents/web%2Fsrc%2Fhooks%2FuseSessionStream.ts?ref=6915c5e2f4310a7e12501e10acbf75115b55cd9e","patch":"@@ -290,9 +290,9 @@ export function useSessionStream(
